import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
const root = import.meta.dirname;
const repo = path.resolve(root, '../..');
const rows = [], owners = [];
function persist() { fs.writeFileSync(path.join(root, 'cli-processes.json'), JSON.stringify(owners, null, 2)); }
for (const mode of ['regular', 'fullscreen']) {
  for (let index = 0; index < 6; index++) {
    const home = path.join(root, 'cli-' + mode + '-' + index);
    const agent = path.join(home, 'agent');
    fs.mkdirSync(path.join(agent, 'config'), { recursive: true });
    fs.writeFileSync(path.join(agent, 'config/settings.json'), JSON.stringify({quietStartup:true,theme:'dark',terminal:{showTerminalProgress:false},compaction:{enabled:false,keepRecentTokens:128,reserveTokens:128}}));
    const args = ['--import', new URL('../../tests/fixtures/alpha-cli-preload.mjs', import.meta.url).href,
      '--import', new URL('./cli-capture.mjs', import.meta.url).href, path.join(repo, 'scripts/superpi.mjs'),
      '--no-session','--no-extensions','--no-tools','--no-context-files','--no-skills','--no-prompt-templates','--no-themes',
      '--tui-mode',mode,'--extension',path.join(repo,'tests/fixtures/alpha-cli-extension.mjs')];
    const env = {...process.env, HOME:home, USERPROFILE:home, XDG_CONFIG_HOME:home, SP_CODING_AGENT_DIR:agent,
      SP_CODING_AGENT_SESSION_DIR:path.join(home,'sessions'), ALPHA_EXIT_KIND:'quit'};
    const start = performance.now();
    const child = spawn(process.execPath,args,{cwd:home,env,windowsHide:true,stdio:'pipe'});
    const owner={pid:child.pid,mode,index,started:new Date().toISOString(),settled:false}; owners.push(owner); persist();
    let stderr='', buffer='', readyAt, quitAt, sendTimer;
    const phases=[];
    child.stdout.resume();
    child.stderr.on('data', data => {
      stderr += data.toString(); buffer += data.toString();
      assert.ok(stderr.length < 65536);
      for (;;) {
        const end=buffer.indexOf('\n'); if(end<0)break;
        const line=buffer.slice(0,end); buffer=buffer.slice(end+1);
        if (!line.startsWith('AUDIT:')) continue;
        const row=JSON.parse(line.slice(6)); phases.push(row);
        if (row.phase==='input-ready-process-age') {
          readyAt=performance.now();
          sendTimer=setTimeout(()=>{quitAt=performance.now();child.stdin.write('/quit\r');},100);
        }
      }
    });
    const timeout=setTimeout(()=>child.kill(),15000);
    const code=await new Promise((resolve,reject)=>{child.once('error',reject);child.once('close',resolve);});
    clearTimeout(timeout);clearTimeout(sendTimer);
    owner.settled=true;owner.code=code;owner.finished=new Date().toISOString();persist();
    assert.equal(code,0,stderr);
    assert.ok(readyAt && quitAt,stderr);
    assert.ok(stderr.includes('ALPHA_EXIT:0:RAW:false'),stderr);
    assert.equal(stderr.split('ALPHA_SESSION_SHUTDOWN').length-1,1,stderr);
    rows.push({mode,index,warmup:index===0,startupMs:readyAt-start,shutdownMs:performance.now()-quitAt,phases,rawRestored:true,shutdownEmissions:1});
  }
}
console.log(JSON.stringify({benchmark:'source-launcher-pipe-backed-startup-quit',node:process.version,scope:'Isolated empty workspace; no tools/bundled resources/network; diagnostic preload; not native PTY or sandbox shutdown',rows},null,2));

